import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  LookupSelect,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const SIZE = 20;

export default function FnSfr02406Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<{ projectId: number | string; status: string }>({ projectId: '', status: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/purchase-requests', role, undefined, {
        projectId: applied.projectId,
        approvalStatus: applied.status,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  const items = data?.items ?? [];
  const total = data?.total ?? 0;
  const pageAmount = items.reduce((sum, row) => sum + Number(row.amount ?? 0), 0);

  const search = () => {
    setPage(0);
    setApplied({ projectId, status });
  };

  const reset = () => {
    setProjectId('');
    setStatus('');
    setPage(0);
    setApplied({ projectId: '', status: '' });
  };

  const columns: Column[] = [
    { key: 'documentNo', label: '문서번호' },
    { key: 'title', label: '품의 제목' },
    { key: 'amount', label: '품의 금액', render: (row) => <Num value={row.amount} /> },
    { key: 'approvalStatus', label: '결재 상태', render: (row) => <Badge value={row.approvalStatus} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 금액 합계', <Num value={pageAmount} />],
          ]}
        />
      </section>

      <section className="box span-12">
        <h2>구매품의 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} placeholder="전체" />
          </Field>
          <Field label="결재 상태">
            <Select value={status} onChange={setStatus} options={STATUSES} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={columns}
          rows={items}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {selected ? (
        <Drawer title="구매품의 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['품의서 ID', String(selected.purchaseRequestId ?? '')],
              ['문서번호', String(selected.documentNo ?? '')],
              ['품의 제목', String(selected.title ?? '')],
              ['품의 금액', <Num value={selected.amount} />],
              ['결재 상태', <Badge value={selected.approvalStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
